const widgetTheme = {
  "titleFont": "headline",
  "bodyFont": "caption",
  "fontDesign": "rounded",
  "corner": 20,
  "padding": 16,
  "spacing": 10,
  "background": "#F2FAF5",
  "surface": "#FFFFFF",
  "foreground": "#193F31",
  "muted": "#607C70",
  "accent": "#328963"
};
// Keep my source
$render(<hstack frame="max" spacing={widgetTheme.spacing} padding={widgetTheme.padding} background={widgetTheme.background} corner={widgetTheme.corner}><vstack spacing="4"><text font={widgetTheme.titleFont} color={widgetTheme.foreground} fontDesign={widgetTheme.fontDesign}>Make it yours</text><text font={widgetTheme.bodyFont} color={widgetTheme.muted} fontDesign={widgetTheme.fontDesign}>Your shapes. Your colors.</text></vstack><image name={"Sample.png"} mode="fill" frame="96,64" corner="12"/></hstack>);
